tailwind.config = {
	theme: {
		extend: {
			fontFamily: {
				display: ["Sora", "sans-serif"],
				body: ["Manrope", "sans-serif"]
			},
			colors: {
				ink: "#0f172a",
				mist: "#e2e8f0",
				sea: "#0f766e",
				mango: "#f97316",
				slateblue: "#1d4ed8"
			}
		}
	}
};

const siteHeader = document.getElementById("site-header");
const menuButton = document.getElementById("mobile-menu-button");
const mobileMenu = document.getElementById("mobile-menu");

const getAnchorOffset = () => {
	const headerHeight = siteHeader ? siteHeader.offsetHeight : 0;
	return headerHeight + 16;
};

const updateScrollMargins = () => {
	const offset = getAnchorOffset();
	document.querySelectorAll("main[id], section[id], h1[id], h2[id]").forEach((element) => {
		element.style.scrollMarginTop = `${offset}px`;
	});
};

const scrollToHash = (hash, updateHistory = false) => {
	if (!hash || hash === "#") return;
	const target = document.querySelector(hash);
	if (!target) return;

	const top = target.getBoundingClientRect().top + window.scrollY - getAnchorOffset();
	window.scrollTo({ top: Math.max(0, top), behavior: "smooth" });

	if (updateHistory) {
		history.pushState(null, "", hash);
	}
};

document.querySelectorAll('a[href^="#"]').forEach((link) => {
	link.addEventListener("click", (event) => {
		const hash = link.getAttribute("href");
		if (!hash || hash === "#") return;
		if (!document.querySelector(hash)) return;

		event.preventDefault();
		scrollToHash(hash, true);
	});
});

window.addEventListener("resize", updateScrollMargins);
window.addEventListener("load", () => {
	updateScrollMargins();
	if (window.location.hash) {
		scrollToHash(window.location.hash);
	}
});
window.addEventListener("hashchange", () => {
	scrollToHash(window.location.hash);
});

if (menuButton && mobileMenu) {
	menuButton.addEventListener("click", () => {
		const isExpanded = menuButton.getAttribute("aria-expanded") === "true";
		menuButton.setAttribute("aria-expanded", String(!isExpanded));
		menuButton.setAttribute("aria-label", isExpanded ? "Abrir menú" : "Cerrar menú");
		mobileMenu.classList.toggle("hidden", isExpanded);
	});

	mobileMenu.querySelectorAll("a").forEach((link) => {
		link.addEventListener("click", () => {
			menuButton.setAttribute("aria-expanded", "false");
			menuButton.setAttribute("aria-label", "Abrir menú");
			mobileMenu.classList.add("hidden");
		});
	});
}

